# AspireC4 Python AppHost sample. It builds the same resource graph as the C# sample AppHost
# (src/src/TestAppHost) and the TypeScript and Go samples, and the shared AppHost contract tests assert
# that all of them draw the same architecture diagram. Keep the samples in step.
#
# The bindings under .aspire/modules are generated by `aspire restore` (or `just py-restore`) from the
# packages in aspire.config.json, including AspireC4.Hosting from the local project. They are not
# committed; never edit them by hand. Python AppHosts are experimental in Aspire 17, which is why
# aspire.config.json turns on features.experimentalPolyglotPython.

import os
import typing
from pathlib import Path

from aspire_app import (
    AspireC4DiagramOptions,
    AspireC4EfDiagramOptions,
    ErdElementStyle,
    LikeC4NodeDetailsAnnotation,
    LikeC4RelationshipDetailsAnnotation,
    PgWebContainerResource,
    PostgresServerResource,
    RedisCommanderResource,
    RedisResource,
    ResourceUrlAnnotation,
    create_builder,
)

VIEW_DESCRIPTION = """This **LikeC4** view was automatically generated from the **Aspire** resource graph, using the **AspireC4** hosting extension.

For more details on all of these tools and components, see:

- [Aspire](https://aspire.dev/)
- [LikeC4](https://likec4.dev/)
- [AspireC4](https://purview.dev/projects/aspirec4/)"""

AZURE_REDIS_DESCRIPTION = """A **Managed Azure** Redis instance allowing fast access to previously cached data and values.

Used with the **Cache Aside** pattern, where the application can check Redis for cached data before falling back to the primary data store (Postgres in this case).

Cache usage will be non-critical and short-lived, ideal for session caching or caching frequently accessed data that doesn't require strong consistency.

Callers must:

- Assume cache is empty
- Populate with a TTL (Time To Live) to prevent stale data
- Ensure keys follow the pattern: `{service}:{key}`"""

LOCAL_REDIS_DESCRIPTION = """For testing **locally**, uses Redis as a container.

When using Azure Managed Redis with `.RunAsContainer()`, the application will differentiate between that and a real Redis resource using `.AddRedis(...)` and pick the correct icon/ technology."""

LOCAL_DEV_GROUP = "Local Dev/ Sync Group"
CLI_RUNTIMES = ("Auto", "Npx", "Pnpm", "Yarn", "Bun", "Deno")


def configure_diagram(opts: AspireC4DiagramOptions) -> None:
    """Sets the diagram's title and view, and wires in the repository's shared images and DSL."""
    opts.with_title("AspireC4 Test App").with_view_title("AspireC4 Architecture").with_view_description(
        VIEW_DESCRIPTION
    )

    assets_path = Path.cwd() / ".." / ".." / "assets"
    images_path = assets_path / "images"
    dsl_path = assets_path / "likec4-extensions"

    if dsl_path.exists():
        opts.with_additional_dsl_folder(str(dsl_path.resolve()))

    if images_path.exists():
        opts.with_image_alias_folder("@", str(images_path.resolve()))

    # Just for the sake of this demo, we'll include the AspireC4 internal resource in the diagram as we
    # reference it from the additional DSLs.
    opts.with_include_aspire_c4_internal_resource(True)

    # Formatting runs `npx likec4 format`, which scans this whole repository when the sample runs from
    # inside it. Every sample AppHost turns it off for the same reason.
    opts.with_format_generated_file(format=False)


def server_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    (
        opts.with_label("AspireC4")
        .with_summary(
            "Describe your Aspire orchestration as a live LikeC4 system architecture diagram - auto generated"
        )
        .with_icon("@/likec4/likec4-logo.svg")
        .with_link("https://purview.dev/projects/aspirec4", title="Learn more about AspireC4")
        .with_link("https://github.com/purview-dev/aspirec4/", title="AspireC4 on GitHub")
        .with_link("https://github.com/kieronlanning", title="Connect with the author on GitHub")
    )


def er_diagram(opts: AspireC4EfDiagramOptions) -> None:
    # The styling is the shared part of the C# sample's (SampleErdStyling.WithSharedSampleStyling), which
    # the AppHost contract asserts for every sample.
    opts.title = "AspireC4 Sample Schema"
    (
        opts.with_table_style("Order*", order_table_style)
        .with_type_style("decimal", decimal_type_style)
        .with_context_palette(["#2563eb", "#16a34a", "#d97706", "#9333ea", "#e11d48", "#0d9488"])
        .with_layout("Right", layer_spacing=160)
        .with_edge_style("SmoothStep")
        .with_animation("Slow")
        .with_legend()
        .with_descriptions()
    )


def order_table_style(style: ErdElementStyle) -> None:
    style.with_accent("#dc2626", dark="#f87171").with_badge("SALES")


def decimal_type_style(style: ErdElementStyle) -> None:
    style.with_accent("#16a34a")


def data_service_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    (
        opts.with_label("Sample Data Service")
        .with_description("Owns the simple and complex sample **Entity Framework Core** models.")
        .with_summary("Sample EF Core models")
    )


def azure_redis_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    (
        opts.with_label("Azure Redis")
        .with_technology("Azure Redis")
        .with_description(AZURE_REDIS_DESCRIPTION)
        .with_summary("Short term caching, used for cross-instance caching")
        .with_link(
            "https://learn.microsoft.com/azure/azure-cache-for-redis/cache-overview",
            title="Learn more about Azure Redis",
        )
        .with_link("https://azure.com/", title="Learn more about Azure")
        .with_link("https://redis.io/", title="Learn more about Redis")
    )


def azure_postgres_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    (
        opts.with_label("Azure Postgres")
        .with_summary("Azure Managed Postgres Flexible Server")
        .with_description("An **Azure Managed** Postgres instance for testing")
        .with_link(
            "https://learn.microsoft.com/azure/postgresql/flexible-server/overview",
            title="Learn more about Azure Postgres Flexible Server",
        )
        .with_link("https://www.postgresql.org/", title="Learn more about Postgres")
        .with_link("https://azure.com/", title="Learn more about Azure")
        .with_metadata("Azure SKU", "Flexible Server x 1 (NON-PROD)")
        .with_metadata("Azure SKU", "Flexible Server x 2 (PROD)")
        .with_metadata("Use Case", "Primary data store")
    )


def local_redis_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    (
        opts.with_description(LOCAL_REDIS_DESCRIPTION)
        .with_summary("Local redis for development")
        .with_link("https://redis.io/", title="Learn more about Redis")
        .with_tag("local-dev")
    )


def local_postgres_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    (
        opts.with_description("For testing Azure Postgres vs. local Postgres")
        .with_summary("Local Postgres for development")
        .with_link("https://www.postgresql.org/", title="Learn more about Postgres")
        .with_tag("local-dev")
    )


def node_app_details(opts: LikeC4NodeDetailsAnnotation) -> None:
    opts.with_label("Sample Node App").with_description(
        "A sample Node.js application that connects to Azure Redis and Azure Postgres"
    )


def with_redis_commander(redis: RedisResource) -> None:
    def commander_details(commander: RedisCommanderResource) -> None:
        commander.with_like_c4_details(
            configure=lambda opts: opts.with_label("Redis Commander").with_summary("Local Redis Web Interface")
        )

    redis.with_redis_commander(configure_container=commander_details)


def with_pg_web(postgres: PostgresServerResource) -> None:
    def pg_web_details(pg_web: PgWebContainerResource) -> None:
        pg_web.with_like_c4_details(
            configure=lambda opts: opts.with_label("PgWeb").with_summary("Local Postgres Web Interface")
        )

    postgres.with_pg_web(configure_container=pg_web_details)


def relationship(label: str, technology: str, kind: str):
    def configure(opts: LikeC4RelationshipDetailsAnnotation) -> None:
        opts.with_label(label).with_technology(technology).with_kind(kind)

    return configure


def health_url(url: ResourceUrlAnnotation) -> None:
    url["url"] = "/health"


def cli_runtime(value: str | None) -> str | None:
    """Maps ASPIREC4_CLI_RUNTIME, case-insensitively, to a LocalCLIRuntime value."""
    return next((runtime for runtime in CLI_RUNTIMES if value and runtime.lower() == value.lower()), None)


with create_builder() as builder:
    # Add LikeC4 visualization to the application. This will allow us to visualize the components and
    # their relationships in a C4 model. We're adding LikeC4 pazzazz to the LikeC4 server resource too.
    c4 = builder.add_aspire_c4(configure=configure_diagram).with_server_like_c4_details(configure=server_details)

    # Allow Dockerfile-based test environments to switch the LikeC4 server to a local JavaScript package
    # manager CLI instead of the Docker container, as the C# sample does.
    runtime = cli_runtime(os.environ.get("ASPIREC4_CLI_RUNTIME"))
    if runtime is not None:
        c4.with_local_cli(runtime=typing.cast(typing.Any, runtime))

    # Adds the d2 ER diagram plus the .NET service that owns the sample Entity Framework Core models. The
    # ER diagram is built from .NET EF Core code, so it always draws .NET projects, whatever the AppHost's
    # language.
    c4.with_entity_framework_diagram(configure=er_diagram)

    (
        builder.add_dotnet_project(
            "data-service", "../../src/src/TestAppHost.DataService/TestAppHost.DataService.csproj"
        )
        .with_entity_framework_model(label="Sample Data Service")
        .with_like_c4_details(configure=data_service_details)
    )

    # Azure managed resources (containers when local).
    azure_redis = (
        builder.add_azure_managed_redis("azure-redis")
        # Run as container when local
        .run_as_container(configure_container=with_redis_commander)
        # Add LikeC4 details to the component for better visualization in the C4 model.
        .with_like_c4_details(configure=azure_redis_details)
    )

    azure_postgres = (
        builder.add_azure_postgres_flexible_server("azure-postgres")
        # Run as container when local
        .run_as_container(configure_container=with_pg_web)
        # Add LikeC4 details to the component for better visualization in the C4 model.
        .with_like_c4_details(configure=azure_postgres_details)
    )

    # Local Dev/ Sync versions...
    local_redis = (
        builder.add_redis("local-redis")
        .with_like_c4_details(configure=local_redis_details)
        .with_like_c4_group(LOCAL_DEV_GROUP)
    )

    local_postgres = (
        builder.add_postgres("local-postgres")
        .with_like_c4_details(configure=local_postgres_details)
        .with_like_c4_group(LOCAL_DEV_GROUP)
    )

    # Our app...
    (
        builder.add_node_app("node-app", "../node-app/", "index.ts")
        # Add LikeC4 details to the component for better visualization in the C4 model.
        .with_like_c4_details(configure=node_app_details)
        .with_npm(install=True)
        .with_http_endpoint(env="PORT")
        .with_url_for_endpoint("http", health_url)
        # These references generate the connections in the C4 model, and give the application the
        # connection strings for these dependencies through Aspire's WithReference.
        .with_like_c4_connection_reference(
            azure_redis, configure=relationship("Caches sessions", "Redis Protocol", "RESP")
        )
        .with_like_c4_connection_reference(
            local_redis, configure=relationship("Caches  sessions (local)", "Redis Protocol", "RESP")
        )
        .with_like_c4_connection_reference(
            azure_postgres, configure=relationship("Persists data", "PostgreSQL / JDBC", "tcp-ip")
        )
        .with_like_c4_connection_reference(
            local_postgres, configure=relationship("Persists data (local)", "PostgreSQL / JDBC", "tcp-ip")
        )
        .wait_for(azure_redis)
        .wait_for(local_redis)
        .wait_for(azure_postgres)
        .wait_for(local_postgres)
    )

    local_postgres.with_like_c4_connection_reference(
        azure_postgres, configure=relationship("syncs with", "PostgreSQL / JDBC", "tcp-ip")
    )
    local_redis.with_like_c4_connection_reference(
        azure_redis, configure=relationship("syncs with", "Redis Protocol", "RESP")
    )

    # Parameters are hidden from the LikeC4 model automatically: they are not architecture, and their
    # values may be secrets.
    builder.add_parameter(
        "testing-resource-parameter", value="This should be hidden from the LikeC4 model"
    ).with_description("This should be hidden from the LikeC4 model")
    builder.add_parameter_from_config("testing-resource-parameter-from-config", "DOTNET_ENVIRONMENT").with_description(
        "This should be hidden from the LikeC4 model"
    )

    builder.run()
